import React, { useState } from 'react';
import {
  FaShoppingCart,
  FaChevronLeft,
  FaChevronRight,
  FaHeart,
  FaShoppingBag,
  FaRegHeart,
  FaThumbsUp,
  FaReply,
  FaStar
} from 'react-icons/fa';
import { useNavigate } from 'react-router-dom';
import ProductCard from '../../Components/ProductCard/ProductCard';
import RatingStars from '../../Components/RatingStars/RatingStars';
import ProductTabs from '../../Components/ProductTabs/ProductTabs';
import Image3 from '../../Assets/Image3.png';
import Image2 from '../../Assets/Image2.png';
import Image1 from '../../Assets/Image1.png';
import R1 from '../../Assets/R1.png';
import R2 from '../../Assets/R2.png';
import R3 from '../../Assets/R3.png';
import R4 from '../../Assets/R4.png';
import visa from '../../Assets/1.png';
import pay from '../../Assets/2.png';
import './ProductReview.css';

const ProductReview = () => {
  const navigate = useNavigate();
  const [selectedSize, setSelectedSize] = useState('M');
  const [selectedColor, setSelectedColor] = useState('red');
  const [currentImageIndex, setCurrentImageIndex] = useState(0);
  const [quantity, setQuantity] = useState(1);
  const [isFavorite, setIsFavorite] = useState(false);
  const [activeTab, setActiveTab] = useState('review');
  const [rating, setRating] = useState(0);
  const [reviewTitle, setReviewTitle] = useState('');
  const [reviewContent, setReviewContent] = useState('');
  const [likedReviews, setLikedReviews] = useState({});

  const product = {
    id: 1,
    name: 'Noah Yellow overcoat',
    price: 5000.0,
    inStock: true,
    colors: ['orange', 'red', 'black'],
    sizes: ['M', 'L', 'XL', 'XXL'],
    images: [Image3, Image2, Image1],
    description: 'This is a stylish Noah Yellow Overcoat designed with bold black and gray accents, adding a modern edge to its vibrant yellow base. Perfect for colder seasons, it blends functionality with high fashion.',
    rating: 4.8,
    reviewCount: 121,
    returnsPolicy: 'Returns accepted within 30 days of purchase.'
  };

  const reviews = [
    {
      id: 1,
      user: 'Nicola Cage',
      title: 'Great Product',
      rating: 5,
      date: '0 Days ago',
      comment: 'There are many variations of passages of Lorem Ipsum available, but the majority have suffered alteration in some form, by injected humour'
    }
  ];

  const ratingDistribution = [
    { stars: 5, percentage: 70 },
    { stars: 4, percentage: 15 },
    { stars: 3, percentage: 10 },
    { stars: 2, percentage: 0 },
    { stars: 1, percentage: 2 }
  ];

  const recommendedProducts = [
    { 
      id: 2, 
      name: 'Black Pins', 
      price: 2500.0, 
      rating: 5, 
      reviewCount: 121,
      image: Image1
    },
    { 
      id: 3, 
      name: 'Winter Jersey', 
      price: 500.0, 
      rating: 5, 
      reviewCount: 121,
      image: R1
    },
    { 
      id: 4, 
      name: 'Over Coat', 
      price: 10000.0, 
      rating: 5, 
      reviewCount: 121,
      image: R2
    },
    { 
      id: 5, 
      name: 'Summer dress', 
      price: 1500.0, 
      rating: 5, 
      reviewCount: 121,
      image: R3
    },
    { 
      id: 6, 
      name: 'Full kit', 
      price: 9000.0, 
      rating: 5, 
      reviewCount: 121,
      image: R4
    }
  ];

  const nextImage = () => {
    setCurrentImageIndex((prev) =>
      prev === product.images.length - 1 ? 0 : prev + 1
    );
  };

  const prevImage = () => {
    setCurrentImageIndex((prev) =>
      prev === 0 ? product.images.length - 1 : prev - 1
    );
  };

  const handleAddToCart = () => {
    navigate('/cart', {
      state: {
        product: {
          ...product,
          selectedSize,
          selectedColor,
          quantity
        }
      }
    });
  };

  const handleBuyNow = () => {
    navigate('/checkout', {
      state: {
        product: {
          ...product,
          selectedSize,
          selectedColor,
          quantity
        }
      }
    });
  };

  const handleSubmitReview = (e) => {
    e.preventDefault();
    if (!rating) {
      alert('Please select a star rating.');
      return;
    }
    console.log({ rating, reviewTitle, reviewContent });
    setRating(0);
    setReviewTitle('');
    setReviewContent('');
    alert('Thank you for your review!');
  };

  const handleLikeReview = (reviewId) => {
    setLikedReviews(prev => ({
      ...prev,
      [reviewId]: !prev[reviewId]
    }));
  };

  return (
    <div className="review-product-page">
      <div className="review-product-container">
        <div className="review-product-main">
          {/* Image Gallery */}
          <div className="review-product-images">
            <div className="review-main-image">
              <img
                src={product.images[currentImageIndex]}
                alt={product.name}
                className="review-product-main-img"
                onError={(e) => {
                  e.target.src = '/images/product/placeholder.jpg';
                }}
              />
              <button className="review-nav-button review-prev" onClick={prevImage}>
                <FaChevronLeft />
              </button>
              <button className="review-nav-button review-next" onClick={nextImage}>
                <FaChevronRight />
              </button>
            </div>
            <div className="review-image-dots-container">
              {product.images.map((_, index) => (
                <span
                  key={index}
                  className={`review-dot ${currentImageIndex === index ? 'review-active' : ''}`}
                  onClick={() => setCurrentImageIndex(index)}
                />
              ))}
            </div>
          </div>

          {/* Product Details */}
          <div className="review-product-details">
            <div className="review-rating-favorite-container">
              <RatingStars rating={product.rating} size="large" />
              <button
                className="review-favorite-button-top"
                onClick={() => setIsFavorite(!isFavorite)}
              >
                {isFavorite ? <FaHeart className="review-filled" /> : <FaRegHeart />}
              </button>
            </div>

            <h1 className="review-product-title">{product.name}</h1>
            <a href="#!" className="review-view-saves">
              View including saves
            </a>

            <div className="review-price-stock">
              <span className="review-price">Rs. {product.price.toFixed(2)}</span>
              <span className="review-stock">{product.inStock ? 'In stock' : 'Out of stock'}</span>
            </div>

            <hr className="review-divider" />

            {/* Color Selector */}
            <div className="review-color-selector">
              <span className="review-color-label">Color</span>
              <div className="review-color-options">
                {product.colors.map((color) => (
                  <div
                    key={color}
                    className={`review-color-option-wrapper ${
                      selectedColor === color ? 'review-selected' : ''
                    }`}
                    onClick={() => setSelectedColor(color)}
                  >
                    <div
                      className="review-color-option"
                      style={{
                        backgroundColor: color.toLowerCase()
                      }}
                      aria-label={color}
                    />
                  </div>
                ))}
              </div>
            </div>

            <hr className="review-divider" />

            {/* Size Selector */}
            <div className="review-size-selector">
              <span className="review-size-label">Size: {selectedSize}</span>
              <div className="review-size-options">
                {product.sizes.map((size) => (
                  <button
                    key={size}
                    className={`review-size-option ${selectedSize === size ? 'review-size-option-selected' : ''}`}
                    onClick={() => setSelectedSize(size)}
                  >
                    {size}
                  </button>
                ))}
              </div>
            </div>

            <div className="review-quantity-control">
              <div className="review-quantity-selector">
                <button 
                  onClick={() => setQuantity(Math.max(1, quantity - 1))}
                  aria-label="Decrease quantity"
                >
                  -
                </button>
                <span aria-live="polite">{quantity}</span>
                <button 
                  onClick={() => setQuantity(quantity + 1)}
                  aria-label="Increase quantity"
                >
                  +
                </button>
              </div>
            </div>
            
            <div className="review-product-actions">
              <button className="review-add-to-cart" onClick={handleAddToCart}>
                <FaShoppingCart /> Add To Cart
              </button>
              <button className="review-buy-now" onClick={handleBuyNow}>
                <FaShoppingBag /> Buy Now
              </button>
            </div>

            <div className="review-secure-checkout">
              <div className="review-secure-icons">
                <img
                  src="/images/product/trustbag.png"
                  alt="Secure Payment"
                />
              </div>
              <p>Guarantee safe & secure checkout</p>
            </div>
          </div>
        </div>

        {/* Tabs Section */}
        <div className="review-tabs-section">
          <ProductTabs activeTab={activeTab} setActiveTab={setActiveTab} />

          <div className="review-tab-content">
            {activeTab === 'description' && (
              <div>
                <h2>Product Description</h2>
                <p>{product.description}</p>
              </div>
            )}
            {activeTab === 'review' && (
              <div className="review-content">
                <div className="customer-feedback-container">
                  <div className="feedback-header">
                    <h3>Customers Feedback</h3>
                  </div>
                  
                  <div className="feedback-summary">
                    <div className="average-rating-box">
                      <div className="average-rating">{product.rating.toFixed(1)}</div>
                      <div className="rating-stars-1">
                        {[...Array(5)].map((_, i) => (
                          <FaStar 
                            key={i} 
                            className={i < Math.floor(product.rating) ? "star filled" : "star"} 
                          />
                        ))}
                      </div>
                      <div className="rating-label">Product Rating</div>
                    </div>
                    
                    <div className="rating-distribution">
                      {ratingDistribution.map((item, index) => (
                        <div key={index} className="rating-row">
                          <div className="rating-bar">
                            <div 
                              className="rating-progress" 
                              style={{ width: `${item.percentage}%` }}
                            ></div>
                          </div>
                          <div className="stars">
                            {[...Array(5)].map((_, i) => (
                              <FaStar 
                                key={i} 
                                className={i < item.stars ? "star filled" : "star"} 
                              />
                            ))}
                          </div>
                          <div className="percentage">{item.percentage}%</div>
                        </div>
                      ))}
                    </div>
                  </div>
                  
                  <div className="reviews-section">
                    <h3>Reviews</h3>
                    
                    {reviews.map((review) => (
                      <div key={review.id} className="review-card">
                        <div className="review-header">
                          <div className="user-info">
                            <div className="user-initial">{review.user.charAt(0)}</div>
                            <div className="user-details">
                              <div className="user-name">{review.user}</div>
                              <div className="review-rating">
                                {[...Array(5)].map((_, i) => (
                                  <FaStar 
                                    key={i} 
                                    className={i < review.rating ? "star filled" : "star"} 
                                  />
                                ))}
                              </div>
                            </div>
                          </div>
                          <div className="review-date">{review.date}</div>
                        </div>
                        
                        <div className="review-body">
                          <p>{review.comment}</p>
                        </div>
                        
                        <div className="review-actions">
                          <button 
                            className={`like-btn ${likedReviews[review.id] ? 'liked' : ''}`}
                            onClick={() => handleLikeReview(review.id)}
                          >
                            <FaThumbsUp /> Like
                          </button>
                          <button className="reply-btn">
                            <FaReply /> Reply
                          </button>
                        </div>
                      </div>
                    ))}
                    
                    <div className="view-all-reviews">
                      <button className="view-all-btn">View All Reviews</button>
                    </div>
                  </div>
                </div>

                <div className="add-review">
                  <h3>Write a Review</h3>
                  <form onSubmit={handleSubmitReview}>
                    <div className="form-group">
                      <label>What is it like to Product?</label>
                      <div className="rating-input">
                        {[1, 2, 3, 4, 5].map((star) => (
                          <FaStar
                            key={star}
                            className={star <= rating ? "star selected" : "star"}
                            onClick={() => setRating(star)}
                          />
                        ))}
                      </div>
                    </div>

                    <div className="form-group">
                      <label htmlFor="review-title">Review Title</label>
                      <input
                        id="review-title"
                        type="text"
                        value={reviewTitle}
                        onChange={(e) => setReviewTitle(e.target.value)}
                        required
                        placeholder="Great Products"
                      />
                    </div>

                    <div className="form-group">
                      <label htmlFor="review">Review Content</label>
                      <textarea
                        id="review"
                        value={reviewContent}
                        onChange={(e) => setReviewContent(e.target.value)}
                        required
                        placeholder="It is a long established fact that a reader will be distracted..."
                      />
                    </div>

                    <button type="submit" className="submit-review-btn">
                      Submit Review
                    </button>
                  </form>
                </div>
              </div>
            )}
            {activeTab === 'returns' && (
              <div>
                <h2>Returns & Exchanges</h2>
                <p>{product.returnsPolicy}</p>
              </div>
            )}
          </div>
        </div>

        {/* Recommended Products */}
        <div className="review-recommended-products">
          <h2>Recommended</h2>
          <p className="review-subtitle">You might want to take a look at these.</p>
          <div className="review-product-grid">
            {recommendedProducts.map((p) => (
              <ProductCard key={p.id} product={p} variant="small" />
            ))}
          </div>
        </div>
      </div>
    </div>
  );
};

export default ProductReview;
